syntax:
// PDLC checklist for any problem
// 1. Analysis  : Input = ?   Output = ?   Processing = ?   Limits = ?
// 2. Design    : pseudocode (START, INPUT, calculate, OUTPUT, END) + flowchart
// 3. Coding    : #include <iostream>, int main() { ... }   -> file.cpp
// 4. Translate : compile file.cpp, read errors, fix bugs, compile again
// 5. Execute   : run with normal, boundary and invalid inputs
// 6. Implement : deliver to users, then maintain (fix and improve)
//
// Flowchart symbols: oval = Start/End, parallelogram = Input/Output,
//                    rectangle = Process, diamond = Decision

sample.code:
#include <iostream>
using namespace std;

int main() {
    double m1 = 70;
    double m2 = 80;
    double average = (m1 + m2) / 2;
    cout << "Average = " << average << endl;
    return 0;
}

#include <iostream>
using namespace std;

int main() {
    int km;
    int fare;
    cout << "Enter distance in km: ";
    cin >> km;
    fare = 50 + 20 * km;
    cout << "Fare = Rs " << fare << endl;
    return 0;
}

#include <iostream>
using namespace std;

int main() {
    int m1, m2, m3;
    cout << "Enter three marks: ";
    cin >> m1 >> m2 >> m3;
    int total = m1 + m2 + m3;
    double average = total / 3.0;
    cout << "Total = " << total << endl;
    cout << "Average = " << average << endl;
    return 0;
}

